class MainActivity : ComponentActivity() { private val notifPermission=registerForActivityResult(ActivityResultContracts.RequestPermission()){};override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)notifPermission.launch(Manifest.permission.POST_NOTIFICATIONS);(getSystemService(NOTIFICATION_SERVICE) as NotificationManager).createNotificationChannel(NotificationChannel("signals","캐치월드 기회 알림",NotificationManager.IMPORTANCE_HIGH));val req=PeriodicWorkRequestBuilder<SignalWorker>(15,TimeUnit.MINUTES).setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build()).build();WorkManager.getInstance(this).enqueueUniquePeriodicWork("catchworld-signal",ExistingPeriodicWorkPolicy.UPDATE,req);setContent{CatchWorldApp()}}}
